import {SlotMain,SlotConfig,SpinResult} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {CAVE_SYMBOLS,caveSymbol as s,caveFreeSequence,CaveTurn} from './CaveFeature';
export class CavePreviewSlot extends SlotMain {
 constructor(private readonly fixture='free'){super();}
 readonly columns=3;readonly rows=3;readonly mode='lines' as const;readonly paylines:number[][]=[];readonly bets=[...BET_LEVELS];
 readonly config:SlotConfig={id:'golden-club-league',title:'수정 갱도',subtitle:'CRYSTAL SHAFT',tag:'무료 피처 초안',color:'#433327',accent:'#cdbb72',description:'3릴 · 10라인 원판 참고\n용의 알 세 칸 · 무료 회전\n용 WILD 대체 · 라인별 당첨\n잭팟 용은 별도 규칙 조사 중',symbols:CAVE_SYMBOLS.map((name,i)=>({id:s(name),name:['망치','용광로','A','K','Q','용 WILD','용의 알','잭팟 용'][i],color:'#cdbb72',weight:0,payout:0}))};
 artResource(id:string){if(!this.config.symbols.some(symbol=>symbol.id===id))throw Error('Unknown Cave art');return 'slot-art-handcrafted-v1/golden-club-league/'+id.slice('golden-club-league-'.length);}
 spin():SpinResult{throw Error('Cave draft is free playback only');}
 demoSpin(bet:number):SpinResult{
  if(!this.bets.includes(bet))throw Error('Invalid bet');const blank=()=>['a','k','q','hammer','cauldron','a','q','k','hammer'].map(s),trigger=blank();
  if(this.fixture==='no-win')return {board:trigger,bet,payout:0,wins:[]};[0,2,7].forEach(cell=>trigger[cell]=s('eggs'));
  // 25 was observed in the video. Payouts below are test inputs, not a paytable.
  const count=this.fixture==='retrigger'?27:25,turns:CaveTurn[]=[];
  for(let n=0;n<count;n++){const board=blank(),wins=[];if(n%8===0){board[0]=s('dragon-wild');board[4]=board[8]=s('k');wins.push({line:0,symbol:s('k'),cells:[0,4,8],amount:bet});}if(this.fixture==='retrigger'&&n===1)[0,2,7].forEach(cell=>board[cell]=s('eggs'));turns.push({board,wins,extraSpins:this.fixture==='retrigger'&&n===1?2:0});}
  return caveFreeSequence(trigger,[{line:-1,symbol:s('eggs'),cells:[0,2,7],amount:bet}],25,turns,bet);
 }
}
