import {SlotMain} from './SlotMain';
import {TrainPreviewSlot} from './TrainPreviewSlot';
import {CavePreviewSlot} from './CavePreviewSlot';
import {ClassicPreviewSlot} from './ClassicPreviewSlot';
import {QuickPreviewSlot} from './QuickPreviewSlot';
import {PhoenixPreviewSlot} from './PhoenixPreviewSlot';
import {OilPreviewSlot} from './OilPreviewSlot';
import {DigitPreviewSlot} from './DigitPreviewSlot';
import {DigitSlot} from './DigitSlot';
import {TowerPreviewSlot} from './TowerPreviewSlot';
/** Explicit local audit imports only. This registry never feeds the lobby or
 * player ownership, and its schematic runs cannot pass production art QA. */
export function schematicDraftSlots(ids:string[],params:URLSearchParams):SlotMain[]{
 const result:SlotMain[]=[];
 if(ids.includes('slot-o-mania'))result.push(new TrainPreviewSlot(params.get('audit-train')||'free'));
 if(ids.includes('golden-club-league'))result.push(new CavePreviewSlot(params.get('audit-cave')||'free'));
 if(ids.includes('realtime-vegas'))result.push(new ClassicPreviewSlot(params.get('audit-classic')||'multiple'));
 if(ids.includes('huuuge-jackpot-club'))result.push(new QuickPreviewSlot(params.get('audit-quick')||'pick'));
 if(ids.includes('billionaire-loop'))result.push(new PhoenixPreviewSlot(params.get('audit-phoenix')||'stack'));
 if(ids.includes('spin-it-gold'))result.push(new OilPreviewSlot(params.get('audit-oil')||'pick'));
 if(ids.includes('double-lucky'))result.push(params.get('audit-digit')==='engine'?new DigitSlot():new DigitPreviewSlot(params.get('audit-digit')||'boost'));
 if(ids.includes('jackpot-rich-night'))result.push(new TowerPreviewSlot(params.get('audit-tower')||'coins'));
 return result;
}
export function isSchematicDraft(slot:SlotMain){return slot instanceof TrainPreviewSlot||slot instanceof CavePreviewSlot||slot instanceof ClassicPreviewSlot||slot instanceof QuickPreviewSlot||slot instanceof PhoenixPreviewSlot||slot instanceof OilPreviewSlot||slot instanceof DigitPreviewSlot||slot instanceof TowerPreviewSlot;}
