import type {SpinResult,Win} from './SlotMain';
export const SERIAL_ART=['pliers','chain','gloves','cleaver','tape_roll','bones','frightened_person','doctor','investigator','masked_figure','plain_wild','nudge_wild','split_wild','ways_device','scatter_lamp'];
export const SERIAL_EFFECT_ART=['infection_pulse','split_sweep','hold_corners','jump_dust','enhancer_cell'];
export const serialSymbol=(name:string)=>'serial-kitchen-'+name;
export const serialVisible=(cell:number,opened:number)=>Number.isInteger(cell)&&cell>=0&&cell<25&&(Math.floor(cell/5)>0&&Math.floor(cell/5)<4||cell%5<opened);
export interface SerialCell {symbol:string;count:number;spins:number;multiplier:number}
export type SerialEffectInput={kind:'ways';cell:number;symbol:string;count:2|3|4;infectious:boolean}|{kind:'split';cell:number};
export interface SerialEffect {kind:'ways'|'split';cell:number;before:SerialCell[];after:SerialCell[];targets:number[]}
export interface SerialTurn {board:string[];effects:SerialEffectInput[];wins:Win[];extension?:[string,string]}
export interface SerialStage {before:SerialCell[];landed:SerialCell[];after:SerialCell[];heldBefore:number[];heldAfter:number[];openedBefore:number;openedAfter:number;effects:SerialEffect[];candidate:Win[];improved:boolean;bestBefore:number;bestAfter:number}
export interface SerialPlayback {initial:SerialCell[];stages:SerialStage[];final:SerialCell[];award:Win[];opened:number}
const copy=(board:SerialCell[])=>board.map(cell=>({...cell}));
/** Hold/improve audit contract. Final-best-only settlement is a documented
 * provisional policy pending the original help; no fixture reaches paid play. */
export function serialSequence(initial:string[],turns:SerialTurn[],bet:number):SpinResult{
 const validate=(board:string[],opened:number)=>{if(board.length!==25||board.some((id,cell)=>serialVisible(cell,opened)?!SERIAL_ART.some(name=>serialSymbol(name)===id):id!==serialSymbol('void')))throw Error('Invalid Serial geometry');};
 if(!Number.isSafeInteger(bet)||bet<1||!turns.length)throw Error('Invalid Serial sequence');validate(initial,0);
 let board=initial.map(symbol=>({symbol,count:1,spins:symbol===serialSymbol('scatter_lamp')?2:0,multiplier:1})),opened=0,held:number[]=[],best=0,award:Win[]=[],ended=false;const first=copy(board),stages:SerialStage[]=[];
 for(const turn of turns){
  if(ended)throw Error('Serial chain already ended');validate(turn.board,opened);
  const before=copy(board),openedBefore=opened,heldBefore=[...held];
  for(const cell of held)if(turn.board[cell]!==board[cell].symbol)throw Error('Serial held symbol changed during respin');
  board=turn.board.map((symbol,cell)=>held.includes(cell)?{...board[cell]}:{symbol,count:1,spins:symbol===serialSymbol('scatter_lamp')?2:0,multiplier:1});
  const landed=copy(board),effects:SerialEffect[]=[];
  for(const effect of turn.effects){
   if(!serialVisible(effect.cell,opened)||held.includes(effect.cell))throw Error('Invalid Serial effect position');
   const prior=copy(board);let targets:number[];
   if(effect.kind==='ways'){
    if(board[effect.cell].symbol!==serialSymbol('ways_device')||!SERIAL_ART.slice(0,10).some(name=>serialSymbol(name)===effect.symbol)||![2,3,4].includes(effect.count))throw Error('Invalid Serial ways reveal');
    targets=effect.infectious?board.flatMap((item,cell)=>item.symbol===effect.symbol||cell===effect.cell?[cell]:[]):[effect.cell];
    targets.forEach(cell=>{board[cell].symbol=effect.symbol;board[cell].count=effect.count;});
   }else{
    if(effect.cell%5!==4||board[effect.cell].symbol!==serialSymbol('split_wild'))throw Error('Serial split requires last-reel wild');
    targets=Array.from({length:5},(_,col)=>Math.floor(effect.cell/5)*5+col).filter(cell=>serialVisible(cell,opened));
    targets.forEach(cell=>{board[cell].count*=2;board[cell].spins*=2;board[cell].multiplier*=2;});
   }
   effects.push({kind:effect.kind,cell:effect.cell,before:prior,after:copy(board),targets});
  }
  const candidate=turn.wins.map(win=>({...win,cells:[...win.cells]}));
  if(candidate.some(win=>!Number.isSafeInteger(win.amount)||win.amount<1||!win.cells.length||win.cells.some(cell=>!serialVisible(cell,opened))))throw Error('Invalid Serial candidate win');
  const value=candidate.reduce((sum,win)=>sum+win.amount,0),bestBefore=best,improved=value>best;
  if(improved){
   const nextHeld=[...new Set(candidate.flatMap(win=>win.cells))];if(held.some(cell=>!nextHeld.includes(cell)))throw Error('Improvement dropped held winning cell');
   best=value;award=candidate;held=nextHeld;
   if(opened<5){if(!turn.extension||turn.extension.some(id=>!SERIAL_ART.some(name=>serialSymbol(name)===id)))throw Error('Missing Serial extension');board[opened]={symbol:turn.extension[0],count:1,spins:0,multiplier:1};board[20+opened]={symbol:turn.extension[1],count:1,spins:0,multiplier:1};opened++;}
  }else ended=true;
  stages.push({before,landed,after:copy(board),heldBefore,heldAfter:[...held],openedBefore,openedAfter:opened,effects,candidate,improved,bestBefore,bestAfter:best});
 }
 if(!ended)throw Error('Serial chain ended before failed improvement');
 return {bet,board:board.map(cell=>cell.symbol),wins:award,payout:best,serialFeature:{initial:first,stages,final:copy(board),award,opened}};
}
