import {WalnutWorkshopSlot} from './WalnutWorkshopSlot';
import {FullMoonKeepSlot} from './FullMoonKeepSlot';
import {isLobbyReadySlot} from './PrioritySlots';
import {applyHitRatePolicy} from './HitRatePolicy';
import {SlotMain} from './SlotMain';
import {LegacySlot} from './LegacySlot';
import {TomeSlot} from './TomeSlot';
import {WolfSlot} from './WolfSlot';
import {RhinoSlot} from './RhinoSlot';
import {TutSlot} from './TutSlot';
import {ChaosSlot} from './ChaosSlot';
import {GladiatorSlot} from './GladiatorSlot';
import {socialFeatureSlots} from './SocialFeatureSlot';

/** Preserve all65 definitions for ownership and audit history. */
export const slots:SlotMain[]=socialFeatureSlots.map(slot=>applyHitRatePolicy(slot.config.id==='tome-of-madness'?new TomeSlot():slot.config.id==='legacy-of-wildead'?new LegacySlot():slot.config.id==='wolf-gold-moon'?new WolfSlot():slot.config.id==='rhino-grand-ways'?new RhinoSlot():slot.config.id==='hunter-book-tutu'?new TutSlot():slot.config.id==='chaos-crew-x'?new ChaosSlot():slot.config.id==='gladiator-lore'?new GladiatorSlot():slot));

// Dedicated social additions: their own natural generators and purchase samplers.
slots.push(new WalnutWorkshopSlot(),new FullMoonKeepSlot());

export const lobbySlots=slots.filter(slot=>isLobbyReadySlot(slot.config.id));
