import {FeatureGame,Random,choose,sampleCells} from './FeatureKit';
import {featureDefinitions} from './FeatureDefinitions';
import {SpinResult} from './SlotMain';
/** Gift wilds, reset-to-three respins, and persistent free-spin wild reels. */
export class CoralPostSlot extends FeatureGame {
 constructor(){super(featureDefinitions['coral-post']);}
 private gift(rng:Random){return choose(rng()<.85?[2,3,4]:rng()<.85?[5,10,15,20]:[25,50,75,100,150,200],rng);}
 spin(bet:number,rng:Random=Math.random):SpinResult{
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  const held=new Map<number,number>(),reels=new Set<number>();let mode='base';
  const roll=():SpinResult=>{
   const board=this.rollBoard(rng),values=Array(20).fill(0),old=Array.from(held.keys());
   for(let i=0;i<20;i++){if(held.has(i)){board[i]=this.wildSymbol;values[i]=held.get(i)!;}else if(rng()<.016){board[i]=this.wildSymbol;values[i]=this.gift(rng);if(mode==='gift')held.set(i,values[i]);}}
   if(mode==='base'&&rng()<.018)this.scatter(board,rng);
   if(mode==='free'){
    for(let col=1;col<4;col++){if(rng()<.075)reels.add(col);if(reels.has(col)){const m=this.gift(rng);for(let row=0;row<4;row++){const i=row*5+col;board[i]=this.wildSymbol;values[i]=m;}}}
   }
   const result=this.evaluate(board,bet,values);result.heldCells=old;result.featureText=mode==='free'?'고정 우편 릴 '+reels.size+'/3':mode==='gift'?'새 선물 → 남은 리스핀 3회':'선물 와일드 배수 합산';return result;
  };
  const base=roll(),rounds=[base];
  if(this.count(base.board,this.bonusSymbol)>=3){mode='free';for(let i=0;i<10;i++){const r=roll();r.roundLabel='우편 프리스핀 '+(i+1)+'/10';rounds.push(r);}return this.finish(rounds,'우편 프리스핀',10);}
  if(this.count(base.board,this.wildSymbol)>=3){mode='gift';base.board.forEach((id,i)=>{if(id===this.wildSymbol)held.set(i,base.symbolValues![i]);});let left=3;
   for(let i=0;left>0&&i<100;i++){const before=held.size,r=roll();left=held.size>before?3:left-1;r.roundLabel='선물 리스핀 · 남은 '+left+'회';rounds.push(r);if(held.size===20)break;}return this.finish(rounds,'선물 리스핀',3);
  }return this.finish(rounds,'');
 }
}
