import {SlotMain,SlotConfig,SpinResult,Win} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {trainFreeSequence,trainStopResult,TrainFreeTurn} from './TrainFeature';
export const TRAIN_SYMBOLS=['conductor','traveler','terrier','money-bag','bell','a','k','q','j','ten','wild','silver-train','golden-train','sticky-wild','prize-star'] as const;
export const trainSymbol=(name:string)=>'slot-o-mania-'+name;
const names=['차장','여행자','테리어','돈주머니','종','A','K','Q','J','10','WILD','은열차','금열차','고정 WILD','별 보상'];
/** Schematic free audit until the dedicated artwork and natural paytable exist. */
export class TrainPreviewSlot extends SlotMain {
 constructor(private readonly fixture='free'){super();}
 readonly columns=6;readonly rows=4;readonly mode='lines' as const;readonly paylines:number[][]=[];readonly bets=[...BET_LEVELS];
 readonly config:SlotConfig={id:'slot-o-mania',title:'미드나잇 레일',subtitle:'MIDNIGHT RAIL',tag:'무료 피처 초안',color:'#243449',accent:'#e7bd76',description:'황금 열차 · 고정 와일드 전환\n열차별 무료 횟수 공개 · 합산\n고정 위치를 유지하며 무료 회전\n별 보상 열차 · 정지 배수 합산',symbols:TRAIN_SYMBOLS.map((name,i)=>({id:trainSymbol(name),name:names[i],color:i>=10?'#e7bd76':'#acd5d0',weight:0,payout:0}))};
 artResource(id:string){if(!this.config.symbols.some(symbol=>symbol.id===id))throw Error('Unknown Train art');return 'slot-art-handcrafted-v1/slot-o-mania/'+id.slice('slot-o-mania-'.length);}
 spin():SpinResult{throw Error('Train draft is free playback only');}
 demoSpin(bet:number):SpinResult{
  if(!this.bets.includes(bet))throw Error('Invalid bet');const s=trainSymbol,blank=()=>Array.from({length:24},(_,cell)=>s(TRAIN_SYMBOLS[(cell*3+Math.floor(cell/6))%10]));
  const trigger=blank();if(this.fixture==='no-win')return {bet,board:trigger,wins:[],payout:0};
  if(this.fixture==='stop'||this.fixture==='stop-with-line'){
   [0,1,7,13].forEach(cell=>trigger[cell]=s('prize-star'));
   const triggerWins:Win[]=[];
   if(this.fixture==='stop-with-line'){
    // Interaction diagnostic only: this is not an asserted original payline.
    [18,19,20].forEach(cell=>trigger[cell]=s('conductor'));
    triggerWins.push({line:0,symbol:s('conductor'),cells:[18,19,20],amount:bet});
   }
   return trainStopResult(trigger,[0,1,7,13],bet*2,[2,5,7,3],2,bet,1,triggerWins);
  }
  const cells=[0,1,6];trigger[0]=s('golden-train');trigger[1]=s('golden-train');trigger[6]=s('silver-train');
  // Short deterministic audit values, not claimed natural spin awards/odds.
  const turns:TrainFreeTurn[]=[];const count=this.fixture==='retrigger'?6:4;
  for(let n=0;n<count;n++){
   const board=blank();board[0]=board[1]=s('sticky-wild');board[2]=s(n%2?'bell':'conductor');if(n===0)board[3]=s('wild');
   const wins:Win[]=n%2===0?[{line:0,symbol:s('conductor'),cells:[0,1,2],amount:bet*(n+1)}]:[];
   turns.push({board,newWilds:[],addedSpins:this.fixture==='retrigger'&&n===1?2:0,wins});
  }
  return trainFreeSequence(trigger,cells,4,turns,s('sticky-wild'),bet,{initialSticky:[0,1],reveals:[{cell:0,spins:1},{cell:1,spins:1},{cell:6,spins:2}],triggerWins:[{line:-1,symbol:s('golden-train'),amount:bet,cells}]});
 }
}
