import {SlotMain,SlotConfig,SpinResult,Win,Cascade} from './SlotMain';
import {cascadeCatalog} from './CascadeCatalog';
const scatterWeights:Record<string,number>={"puppy-sky": 3.35302734375, "space-scrap": 3.27099609375, "mushroom-rush": 0.73681640625, "pirate-stars": 3.35302734375};
type Spec=typeof cascadeCatalog[number];
/** Original-themed implementations of researched anywhere/cluster rules. */
export class CascadeSlot extends SlotMain {
 readonly columns:number;readonly rows:number;readonly mode='clusters' as const;readonly hasBonus=true;readonly maxWin:number;readonly config:SlotConfig;
 get bonusSymbol(){return this.spec.id+'-bonus';}
 get bonusTriggerCount(){return this.spec.scatterTrigger;}
 constructor(readonly spec:Spec){super();this.columns=spec.columns;this.rows=spec.rows;this.maxWin=spec.maxWin;this.config={id:spec.id,title:spec.title,subtitle:spec.subtitle,tag:spec.winType==='anywhere'?'ANYWHERE · BONUS':'CLUSTER · BONUS',color:spec.colors[0],accent:spec.colors[1],description:spec.rules.join('\n'),symbols:spec.symbolNames.map((name,i)=>({id:spec.id+'-'+i,name,art:spec.symbolArt[i],color:[spec.colors[1],spec.colors[2],'#e993b6','#b3aaef'][i%4],weight:4+i*2,payout:spec.paytable[i][0]/spec.divisor})).concat([{id:spec.id+'-bonus',name:'SCATTER',art:'parcel',color:'#ffe49b',weight:scatterWeights[spec.id]||1.2,payout:0},{id:spec.id+'-multi',name:'배수',art:'star',color:'#fff0b6',weight:spec.mechanic==='marks'?0:1,payout:0}])};}
 private regular(id:string){return this.config.symbols.findIndex(s=>s.id===id);}
 evaluate(board:string[],bet:number):SpinResult{
  if(board.length!==this.columns*this.rows||!this.bets.includes(bet)||board.some(id=>this.regular(id)<0))throw Error('Invalid cascade board');
  const groups:number[][]=[];
  if(this.spec.winType==='anywhere'){for(let i=0;i<this.spec.symbolNames.length;i++)groups.push(board.map((id,at)=>this.regular(id)===i?at:-1).filter(at=>at>=0));}
  else{const seen=new Set<number>();for(let start=0;start<board.length;start++){if(seen.has(start))continue;const group:number[]=[],queue=[start];seen.add(start);while(queue.length){const at=queue.pop()!;group.push(at);for(const to of [at-this.columns,at+this.columns,...(at%this.columns?[at-1]:[]),...(at%this.columns<this.columns-1?[at+1]:[])])if(to>=0&&to<board.length&&!seen.has(to)&&board[to]===board[start]){seen.add(to);queue.push(to);}}groups.push(group);}}
  const wins:Win[]=[];for(const cells of groups){if(cells.length<this.spec.threshold)continue;const index=this.regular(board[cells[0]]),table=this.spec.paytable[index];if(!table)continue;const amount=Math.round(bet*table[Math.max(0,table.length-cells.length)]/this.spec.divisor);if(amount)wins.push({line:-1,symbol:board[cells[0]],cells,amount});}
  return{board:[...board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0)};
 }
 spin(bet:number,rng:()=>number=Math.random):SpinResult{
  const state={marks:Array(this.columns*this.rows).fill(0) as number[],multi:0};const base=this.roll(bet,rng,false,state);state.marks.fill(0);state.multi=0;
  return this.freeSpinSequence(base,()=>this.roll(bet,rng,true,state),round=>{const count=Math.max(...round.cascades!.map(s=>s.board.filter(id=>id===this.spec.id+'-bonus').length));if(round===base)return count<this.spec.scatterTrigger?0:this.spec.mechanic==='marks'?[10,12,15,20,30][Math.min(7,count)-3]:this.spec.freeSpins;return count>=3?(this.spec.mechanic==='marks'?[10,12,15,20,30][Math.min(7,count)-3]:5):0;});
 }
 private roll(bet:number,rng:()=>number,free:boolean,state:{marks:number[];multi:number}):SpinResult{
  if(!this.bets.includes(bet))throw Error('Invalid bet');const count=this.columns*this.rows,extra=this.spec.id+'-multi',bon=this.spec.id+'-bonus';let serial=0;
  const features=new Map<number,{token:number;value:number}>(),seenFeatures=new Set<number>();let multiplier=0;
  const choose=(at:number)=>{let id=this.pick(rng);if(id===extra&&this.spec.mechanic==='bomb'&&!free)id=this.config.symbols[this.spec.symbolNames.length-1].id;if(id===extra){const values=[2,2,2,3,3,4,5,8,10,15,20,50,100,this.spec.mechanic==='bomb'?100:500];features.set(at,{token:++serial,value:values[Math.min(values.length-1,Math.floor(rng()*rng()*values.length))]});}return id;};
  let board=Array.from({length:count},(_,i)=>choose(i)),marks=free?[...state.marks]:Array<number>(count).fill(0);const cascades:Cascade[]=[],wins:Win[]=[];
  for(let step=0;step<30;step++){
   const result=this.evaluate(board,bet),paid=result.wins.map(w=>{const m=this.spec.mechanic==='marks'?Math.max(1,w.cells.reduce((n,i)=>n+(marks[i]>=2?marks[i]:0),0)):1;return{...w,multiplier:m,amount:w.amount*m};});
   if(paid.length){for(const [at,f]of Array.from(features)){if(board[at]===extra&&!seenFeatures.has(f.token)){seenFeatures.add(f.token);multiplier+=f.value;}}}
   const next=[...marks];if(this.spec.mechanic==='marks')for(const i of new Set(paid.flatMap(w=>w.cells)))next[i]=marks[i]===0?1:Math.min(128,marks[i]*2);
   const stage:Cascade={board:[...board],wins:paid,payout:paid.reduce((n,w)=>n+w.amount,0),multiplier:Math.max(1,...paid.map(w=>w.multiplier)),cellMultipliers:this.spec.mechanic==='marks'?[...marks]:Array.from({length:count},(_,i)=>features.get(i)?.value||0),nextMultipliers:next,drops:[]};cascades.push(stage);wins.push(...paid);marks=next;
   if(!paid.length||step===29)break;
   const removed=new Set(paid.flatMap(w=>w.cells)),oldFeatures=new Map(features),nextBoard=Array<string>(count);features.clear();
   for(let col=0;col<this.columns;col++){const kept=Array.from({length:this.rows},(_,r)=>r*this.columns+col).filter(i=>!removed.has(i)),incoming=this.rows-kept.length;for(let row=0;row<this.rows;row++){const to=row*this.columns+col,from=row<incoming?(row-incoming)*this.columns+col:kept[row-incoming],symbol=from<0?choose(to):board[from];if(from>=0&&oldFeatures.has(from))features.set(to,oldFeatures.get(from)!);nextBoard[to]=symbol;stage.drops.push({from,to,symbol});}}
   board=nextBoard;
  }
  if(free)state.marks=[...marks];let payout=wins.reduce((n,w)=>n+w.amount,0),adjustment:SpinResult['adjustment'];
  if(multiplier>0&&payout>0){if(free&&this.spec.mechanic==='sky')state.multi+=multiplier;const m=free&&this.spec.mechanic==='sky'?state.multi:multiplier;adjustment={line:-1,symbol:extra,cells:[],amount:payout*(m-1),multiplier:m,caption:'배수 합계 ×'+m};wins.push(adjustment);payout+=adjustment.amount;}
  const scatterCount=board.filter(id=>id===bon).length;let scatterAward:Win|undefined;
  if(this.spec.mechanic!=='marks'&&scatterCount>=4){const amount=bet*(scatterCount===4?3:scatterCount===5?5:100);scatterAward={line:-1,symbol:bon,cells:board.map((id,i)=>id===bon?i:-1).filter(i=>i>=0),amount};wins.push(scatterAward);payout+=amount;}
  return{board,bet,payout,wins,cascades,adjustment,scatterAward,featureText:this.spec.mechanic==='sky'?'프리스핀 누적 배수 ×'+Math.max(1,state.multi):this.spec.mechanic==='bomb'?'이번 텀블 폭탄 합계 ×'+Math.max(1,multiplier):'당첨 칸 배수 유지'};
 }
 demoSpin(bet:number):SpinResult{let seed=88231;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};for(let i=0;i<10000;i++){const r=this.spin(bet,rng);if(r.payout>0&&!r.rounds)return r;}throw Error('No demo found');}
}
export const cascadeSlots=cascadeCatalog.map(spec=>new CascadeSlot(spec));
