import {LocalizedNotice} from './NoticeText';
export interface Gift {coins:number;tickets:number;costumes:string[];unlocks:string[];}
export interface MailReward extends LocalizedNotice {id:string;audience:string;createdAt:number;expiresAt:number;status:'active'|'revoked';gift:Gift;noticeId?:string;}
export function validateGift(value:any,allowEmpty=false):Gift {
 if(!value||!Number.isSafeInteger(value.coins)||value.coins<0||value.coins>1e9||!Number.isSafeInteger(value.tickets)||value.tickets<0||value.tickets>1e9)throw Error('코인·티켓 수량을 확인해 주세요.');
 for(const key of ['costumes','unlocks'])if(!Array.isArray(value[key])||value[key].length>100||value[key].some((id:unknown)=>typeof id!=='string'||!/^[a-z0-9-]{1,80}$/.test(id))||new Set(value[key]).size!==value[key].length)throw Error('첨부 상품 목록을 확인해 주세요.');
 if(!allowEmpty&&!value.coins&&!value.tickets&&!value.costumes.length&&!value.unlocks.length)throw Error('한 개 이상의 선물을 선택해 주세요.');
 return {coins:value.coins,tickets:value.tickets,costumes:[...value.costumes],unlocks:[...value.unlocks]};
}
export function canClaimMail(mail:MailReward,uid:string,now:number){return mail.status==='active'&&(mail.audience==='all'||mail.audience===uid)&&mail.createdAt<=now&&now<mail.expiresAt;}
export function applyGift<T extends {coins:number;tickets:number;owned:string[];unlocked:string[]}>(save:T,value:Gift):T {
 const gift=validateGift(value),coins=save.coins+gift.coins,tickets=save.tickets+gift.tickets;
 if(!Number.isSafeInteger(coins)||!Number.isSafeInteger(tickets))throw Error('보유 가능한 수량을 초과했습니다.');
 return {...save,coins,tickets,owned:Array.from(new Set([...save.owned,...gift.costumes])),unlocked:Array.from(new Set([...save.unlocked,...gift.unlocks]))};
}
