import type {SpinResult,Win} from './SlotMain';
import {WolfMoneyToken,wolfMoneyStart,wolfMoneyRespin,wolfMoneyCollect} from './WolfMoney';

export interface WolfMoneyDisplay {
 cell:number;
 kind:WolfMoneyToken['kind'];
 /** Shared with final settlement so purchased-bonus scaling reaches every frame. */
 award:Win;
}
export interface WolfMoneyPlayback {
 triggerBoard?:string[];
 triggerWins?:Win[];
 initial:WolfMoneyDisplay[];
 stages:{before:WolfMoneyDisplay[];after:WolfMoneyDisplay[];landed:number[];remainingBefore:number;remainingAfter:number}[];
 collection:WolfMoneyDisplay[];
 mega?:Win;
}
const ID='wolf-gold-moon',MONEY=ID+'-money',VOID=ID+'-void';
const board=(tokens:readonly {cell:number}[])=>{
 const held=new Set(tokens.map(t=>t.cell));return Array.from({length:15},(_,cell)=>held.has(cell)?MONEY:VOID);
};
/** Converts a complete, already sampled money sequence. No RNG, filler rounds,
 * ordinary line awards, or free-spin progress is invented here. A parent game
 * can attach this result between free-spin rounds without spending a free spin. */
export function wolfMoneyResult(bet:number,initial:readonly WolfMoneyToken[],landings:readonly (readonly WolfMoneyToken[])[],trigger?:{board:readonly string[];wins:readonly Win[]}):SpinResult{
 let state=wolfMoneyStart(initial);
 const steps=landings.map(landed=>{const step=wolfMoneyRespin(state,landed);state=step.after;return step;});
 const collected=wolfMoneyCollect(state,bet);
 const awards=new Map(state.tokens.map(token=>[token.cell,{line:-1,symbol:MONEY,cells:[token.cell],amount:bet*token.multiple} as Win]));
 const display=(tokens:readonly WolfMoneyToken[]):WolfMoneyDisplay[]=>tokens.map(token=>{
  const award=awards.get(token.cell);if(!award)throw Error('Unshared Wolf money award');
  return{cell:token.cell,kind:token.kind,award};
 });
 const mega:Win|undefined=collected.megaPayout?{line:-1,symbol:ID+'-mega',cells:state.tokens.map(t=>t.cell),amount:collected.megaPayout}:undefined;
 const triggerWins=trigger?.wins.map(win=>({...win,cells:[...win.cells]}))||[],moneyWins=[...awards.values(),...(mega?[mega]:[])],wins=[...triggerWins,...moneyWins];
 if(moneyWins.reduce((sum,win)=>sum+win.amount,0)!==collected.payout)throw Error('Wolf money settlement mismatch');
 return {bet,board:board(state.tokens),openingBoard:trigger?[...trigger.board]:board(initial),wins,payout:wins.reduce((sum,win)=>sum+win.amount,0),moneyCells:state.tokens.map(t=>t.cell),
  wolfMoneyFeature:{triggerBoard:trigger?[...trigger.board]:undefined,triggerWins:triggerWins.length?triggerWins:undefined,initial:display(initial),stages:steps.map(step=>({before:display(step.before.tokens),after:display(step.after.tokens),
   landed:step.landed.map(t=>t.cell),remainingBefore:step.before.remaining,remainingAfter:step.after.remaining})),collection:display(state.tokens),mega},featureName:'머니 리스핀'};
}
