import type {SpinResult,Cascade,Win} from './SlotMain';
import {vikingRagnarok} from './VikingRagnarok';
import {vikingRagnarokMultiplier} from './VikingFeatures';
import {vikingOrdinaryResult,vikingSymbol} from './VikingResult';
import {vikingDestructionStage} from './VikingEffectResult';
import {vikingCapAwards} from './VikingSettlement';

/** Standalone free-round adapter: no preceding base award is accepted here.
 * The multiplier's relation to a triggering paid win is still unverified.
 * All destruction/cascade events remain in order; only the last no-win board
 * ends playback. Intermediate no-win boards must continue to the next effect.
 */
export function vikingStandaloneRagnarokResult(bet:number,source:ReturnType<typeof vikingRagnarok>):SpinResult{
 const cascades:Cascade[]=[],effects=new Set<string>();let previous:number[]|undefined,count=0,rawPayout=0;
 for(const event of source.events){
  if(event.kind==='cascades'){
   const segment=event.segment,opening=segment.steps[0]?.before||segment.board;
   if(previous&&opening.some((s,c)=>s!==previous![c]))throw Error('Discontinuous Viking Ragnarok cascade');
   const subtotal=segment.steps.reduce((sum,step)=>sum+step.wins.reduce((n,w)=>n+w.amount,0),0);
   const part=vikingOrdinaryResult(bet,{...segment,subtotal});
   cascades.push(...part.cascades!.slice(0,-1));
   rawPayout+=subtotal;count+=segment.steps.reduce((sum,step)=>sum+step.removed.length,0);previous=[...segment.board];
  }else{
   if(!previous||event.effect.before.some((s,c)=>s!==previous![c])||effects.has(event.effect.kind))throw Error('Invalid Viking Ragnarok destruction sequence');
   effects.add(event.effect.kind);cascades.push(vikingDestructionStage(event.effect));previous=[...event.effect.after];
  }
 }
 if(effects.size!==4||source.events[source.events.length-1]?.kind!=='cascades'||!previous||source.board.some((s,c)=>s!==previous![c])||count!==source.winningSymbols||rawPayout!==source.unmultipliedSubtotal||source.multiplier!==vikingRagnarokMultiplier(count))throw Error('Incomplete Viking Ragnarok settlement');
 const board=source.board.map(vikingSymbol),multiplier=source.multiplier;
 cascades.push({board:[...board],wins:[],payout:0,multiplier:1,cellMultipliers:Array(49).fill(0),nextMultipliers:Array(49).fill(0),drops:[],vikingCharge:{before:count,after:count}});
 const limited=vikingCapAwards(cascades,bet,multiplier),wins:Win[]=cascades.flatMap(stage=>stage.wins),extra=limited.extra;
 const adjustment=extra?{line:-1,symbol:'viking-ragnarok-multiplier',cells:[],amount:extra,multiplier,caption:limited.capReached?'최대 당첨 · 5,000배':'라그나로크 최종 배수 ×'+multiplier}:undefined;
 if(adjustment)wins.push(adjustment);
 return {bet,board,openingBoard:[...cascades[0].board],wins,payout:limited.payout,cascades,adjustment,featureName:'라그나로크',freeSpinsAwarded:1,vikingRagnarok:{winningSymbols:count,multiplier,rawPayout,capReached:limited.capReached,uncappedPayout:limited.uncappedPayout}};
}
